import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Arrange: sign in so the session cookie is stored in this request context's cookie jar
  const login = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: PASSWORD },
  });
  expect(login.status(), await login.text()).toBe(200);
  const sessionSet = login.headersArray().find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(sessionSet, "sign-in should set the session cookie").toBeTruthy();

  // Act
  const response = await request.post("/api/auth/logout");

  // Assert
  expect(response.status(), await response.text()).toBe(204);
  const clearing = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(clearing.length, "logout should send a session Set-Cookie header").toBeGreaterThan(0);
  const cleared = clearing.some((h) =>
    /^session=(;|"";|$)/.test(h.value) ||
    /max-age=0(;|$)/i.test(h.value) ||
    /expires=Thu, 01 Jan 1970/i.test(h.value),
  );
  expect(cleared, `session cookie should be cleared, got: ${clearing.map((h) => h.value).join(" | ")}`).toBeTruthy();
});
